#!/bin/sh
# Writes rcsdk_monocypher_names.h: every global symbol the vendored Monocypher
# defines, renamed with the prefix rcsdk_. Run it after updating Monocypher,
# from the repository root, with a build tree:
#   third_party/monocypher/rename-symbols.sh build/release
# NM may name an nm that reads the tree's object format (llvm-nm).
set -eu
nm=${NM:-nm}
out=third_party/monocypher/rcsdk_monocypher_names.h
# Mach-O prefixes every C symbol with an underscore; a tree where every
# symbol has one is Mach-O, and loses it.
list=$(find "$1/third_party/CMakeFiles/rcsdk_monocypher.dir" \( -name '*.o' -o -name '*.obj' \) \
    -exec "$nm" -g --defined-only {} + 2>/dev/null | awk 'NF == 3 { print $3 }' | grep -v -e '^\.' -e ':' | sort -u)
if ! echo "$list" | grep -qv '^_'; then list=$(echo "$list" | sed -e 's/^_//'); fi
names=$(echo "$list" | sed -e 's/^rcsdk_//' | sort -u) # Trees built with the header already have the prefix.
{
    echo '/* Every global symbol of the vendored Monocypher gets the prefix rcsdk_, so'
    echo ' * that a host linking its own Monocypher never clashes with the copy inside'
    echo ' * the SDK, static builds included (hidden visibility only applies to shared'
    echo ' * ones). Included first by every Monocypher source (third_party/CMakeLists.txt)'
    echo ' * and by the SDK code that calls Monocypher. Generated by rename-symbols.sh. */'
    echo '#ifndef RCSDK_MONOCYPHER_NAMES_H'
    echo '#define RCSDK_MONOCYPHER_NAMES_H'
    for name in $names; do
        echo "#define $name rcsdk_$name"
    done
    echo '#endif'
} > "$out"
echo "$out: $(echo "$names" | wc -l | tr -d ' ') symbols"
